import collections
import platform

def _t():

    class _SelfNS:
        pass
    self = _SelfNS()
    self.linux_alpha = platform.system().startswith('Linux') and platform.machine().startswith('alpha')
    self.system_round_bug = round(5000000000000000.0 + 1) != 5000000000000000.0 + 1

    class M:
        """Test mapping interface versus possible calls from eval()."""

        def __getitem__(self, key):
            if key == 'a':
                return 12
            raise KeyError

        def keys(self):
            return list('xyz')
    m = M()
    g = globals()
    assert eval('a', g, m) == 12, ('assertEqual', eval('a', g, m), 12)
    try:
        eval(*('b', g, m))
    except NameError:
        pass
    assert eval('dir()', g, m) == list('xyz'), ('assertEqual', eval('dir()', g, m), list('xyz'))
    assert eval('globals()', g, m) == g, ('assertEqual', eval('globals()', g, m), g)
    assert eval('locals()', g, m) == m, ('assertEqual', eval('locals()', g, m), m)
    try:
        eval(*('a', m))
    except TypeError:
        pass

    class A:
        """Non-mapping"""
        pass
    m = A()
    try:
        eval(*('a', g, m))
    except TypeError:
        pass

    class D(dict):

        def __getitem__(self, key):
            if key == 'a':
                return 12
            return dict.__getitem__(self, key)

        def keys(self):
            return list('xyz')
    d = D()
    assert eval('a', g, d) == 12, ('assertEqual', eval('a', g, d), 12)
    try:
        eval(*('b', g, d))
    except NameError:
        pass
    assert eval('dir()', g, d) == list('xyz'), ('assertEqual', eval('dir()', g, d), list('xyz'))
    assert eval('globals()', g, d) == g, ('assertEqual', eval('globals()', g, d), g)
    assert eval('locals()', g, d) == d, ('assertEqual', eval('locals()', g, d), d)
    eval('[locals() for i in (2,3)]', g, d)
    eval('[locals() for i in (2,3)]', g, collections.UserDict())

    class SpreadSheet:
        """Sample application showing nested, calculated lookups."""
        _cells = {}

        def __setitem__(self, key, formula):
            self._cells[key] = formula

        def __getitem__(self, key):
            return eval(self._cells[key], globals(), self)
    ss = SpreadSheet()
    ss['a1'] = '5'
    ss['a2'] = 'a1*6'
    ss['a3'] = 'a2*7'
    assert ss['a3'] == 210, ('assertEqual', ss['a3'], 210)

    class C:

        def __getitem__(self, item):
            raise KeyError(item)

        def keys(self):
            return 1
    try:
        eval(*('dir()', globals(), C()))
    except TypeError:
        pass
